    <?php if (empty(mynet_user('branch_id')) && mynet_user('role') !== 'pelanggan'): ?><div class="form-field"><label>Cabang</label><select name="branch_id" required><option value="">Pilih cabang</option><?php foreach ($branches as $branch): ?><option value="<?= (int) $branch['id'] ?>"><?= esc($branch['name']) ?></option><?php endforeach; ?></select></div><?php endif; ?>
