<section class="panel table-panel ticket-table"><div class="panel-heading"><div><h2>Daftar tiket</h2><p><?= count($tickets) ?> tiket terbaru dalam cakupan akses Anda.</p></div><label class="table-search"><span>⌕</span><input type="search" placeholder="Cari tiket..." data-table-search></label></div>
    <?php if ($tickets): ?><div class="table-wrap"><table class="data-table workspace-table"><thead><tr><th>NOMOR</th><th>MASALAH</th><th>PELANGGAN</th><th>PRIORITAS</th><th>TEKNISI</th><th>STATUS</th><th>JADWAL</th><th>AKSI</th></tr></thead><tbody><?php foreach ($tickets as $ticket): ?><tr><td class="cell-strong"><?= esc($ticket['ticket_no']) ?></td><td><strong><?= esc($ticket['title']) ?></strong><small class="table-secondary"><?= esc(ucfirst($ticket['category'])) ?></small><details class="ticket-history"><summary>Uraian &amp; riwayat</summary><p><?= nl2br(esc($ticket['description'])) ?></p><?php if ($ticket['resolution']): ?><p><strong>Penyelesaian:</strong> <?= nl2br(esc($ticket['resolution'])) ?></p><?php endif; ?><ol><?php foreach ($ticketUpdates[$ticket['id']] ?? [] as $update): ?><li><strong><?= esc(ucfirst(str_replace('_', ' ', $update['status']))) ?></strong> · <?= esc($update['operator_name'] ?? 'API') ?><small><?= esc($update['created_at']) ?></small><?php if ($update['comment']): ?><span><?= nl2br(esc($update['comment'])) ?></span><?php endif; ?></li><?php endforeach; ?></ol></details></td><td><?= esc($ticket['customer_name'] ?? 'Internal') ?></td><td><span class="status-pill priority-<?= esc($ticket['priority']) ?>"><?= esc(ucfirst($ticket['priority'])) ?></span></td><td><?= esc($ticket['technician_name'] ?? 'Belum ditugaskan') ?></td><td><span class="status-pill status-<?= esc($ticket['status']) ?>"><?= esc(match ($ticket['status']) { 'in_progress' => 'Dikerjakan', 'resolved' => 'Terselesaikan', default => ucfirst($ticket['status']) }) ?></span></td><td><?= esc($ticket['scheduled_at'] ?? '—') ?></td><td class="ticket-actions">
        <?php if ($canAssign && ! in_array($ticket['status'], ['closed'], true)): ?><details class="row-menu"><summary>Tugaskan</summary><form method="post" action="<?= site_url('/tickets/' . $ticket['id'] . '/assign') ?>"><?= csrf_field() ?><select name="technician_id" required><option value="">Teknisi</option><?php foreach ($technicians as $technician): ?><option value="<?= (int) $technician['id'] ?>" <?= (int) $ticket['assigned_to'] === (int) $technician['id'] ? 'selected' : '' ?>><?= esc($technician['full_name']) ?></option><?php endforeach; ?></select><input type="datetime-local" name="scheduled_at" aria-label="Jadwal kunjungan"><button type="submit">Simpan</button></form></details><?php endif; ?>
        <?php if (! in_array($ticket['status'], ['closed'], true) && (mynet_user('role') === 'superadmin' || in_array(mynet_user('role'), ['administrator', 'admin', 'noc'], true) || (mynet_user('role') === 'teknisi' && (int) $ticket['assigned_to'] === (int) mynet_user('id')))): ?><details class="row-menu"><summary>Status</summary><form method="post" action="<?= site_url('/tickets/' . $ticket['id'] . '/status') ?>"><?= csrf_field() ?><select name="status"><option value="in_progress">Dikerjakan</option><option value="resolved">Terselesaikan</option><?php if ($canAssign): ?><option value="closed">Ditutup</option><?php endif; ?></select><input name="comment" placeholder="Catatan"><input name="resolution" placeholder="Hasil perbaikan"><button type="submit">Perbarui</button></form></details><?php endif; ?>
    </td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="empty-state"><span>▣</span><strong>Belum ada tiket</strong><p>Tiket baru yang dibuat akan muncul di antrean ini.</p></div><?php endif; ?>
</section>
